    },
    {
      "card_ids": ["C01"],
      "claim": "Asciminib has an absolute oral bioavailability of approximately 73% in humans, supporting high F for a complex oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Suvorexant mean absolute bioavailability is 82% under fasted conditions, supporting high F for a heteroaromatic amide-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Elinzanetant oral bioavailability is 36.7%, moderate but still above the 20% threshold, supporting high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Emtricitabine absolute bioavailability is 93% and unaffected by food, supporting high F and food-independence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Lamivudine absolute bioavailability averaged 82% across doses, supporting high F for a small polar drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence, with high transfer scores, reports oral bioavailability values at or above the 20% threshold (mostly 36–93%), and fed-state data are neutral-to-favorable; therefore the query is predicted to have high absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct pharmacokinetic measurement exists for the query molecule itself.",
    "Several high-F analogues are nucleosides with different absorption mechanisms, though non-nucleoside analogues also support high F.",
    "Fed-state-specific data are limited to a few analogues, but those available show no reduction and one shows increased F after a meal.",
    "No retrieved evidence indicates low oral bioavailability for any close analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

